type Measurement = {
  organizationId: string;
  firstNavigationMs: number | null;
  firstNavigationValid: boolean;
  samples: { durationMs: number; valid: boolean }[];
  startedAt: number | null;
  index: number;
};
const ready = '[data-cy="audit-export-ready"]';
const generate = '[data-cy="audit-export-generate"]';
const csvButton = '[data-cy="audit-export-download"]';
const metaButton = '[data-cy="audit-export-metadata"]';
const headers = [
  'event_id',
  'occurred_at',
  'actor_id',
  'action',
  'entity_type',
  'entity_id',
  'organization_id',
  'outcome',
];
let releaseResponse: (() => void) | undefined;
let measurement: Measurement | null = null;
function route(c: Fixture) {
  return `/administracion/organizaciones/${c.organizationId}/auditoria`;
}
function localField(value: string) {
  const parts = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'America/Santiago',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(value));
  const get = (type: string) => parts.find((part) => part.type === type)!.value;
  return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`;
}
function prepare(profile = 'functional') {
  return cy
    .task<Fixture>(
      'auditExport:prepare',
      { profile },
      { log: false, timeout: 120_000 },
    )
    .then((fixture) =>
      cy
        .task<Session>('identity:login', 'ADMIN', { log: false })
        .then((admin) => cy.wrap({ ...fixture, admin }, { log: false })),
    );
}
function visit(c: Context, beforeLoad?: (window: Cypress.AUTWindow) => void) {
  cy.visit(route(c), {
    onBeforeLoad(window) {
      window.localStorage.setItem(
        'alunza.auth.127.0.0.1:18421',
        JSON.stringify(c.admin),
      );
      beforeLoad?.(window);
    },
  });
  cy.get('[data-testid="audit-list-ready"]').should('be.visible');
  // Fix the fixture period via the actual form. Export audit events generated
  // by earlier iterations are outside this cut and cannot inflate capacity.
  cy.get('[name="from"]').should('be.enabled').clear().type(localField(c.from));
  cy.get('[name="asOf"]').clear().type(localField(c.asOf));
  cy.get(generate).should('be.disabled');
  apply();
  cy.get('[data-testid="audit-list-ready"]').should(
    'contain.text',
    `Registros encontrados: ${c.oracle.total}.`,
  );
  cy.get(generate).should('be.enabled');
}
function apply() {
  cy.get('[data-cy="audit-filters"]')
    .contains('button', 'Aplicar filtros')
    .click();
}
function startExport(c: Context, alias = 'createdExport') {
  // Retire this observer after its POST so later exports cannot queue a stale
  // response under an alias that another step already consumed.
  cy.intercept({
    method: 'POST',
    pathname: `/api/v1/organizations/${c.organizationId}/audit-exports`,
    times: 1,
  }).as(alias);
  cy.get(generate).click();
  return cy.wait(`@${alias}`).then(({ request, response }) => {
    expect(response!.statusCode).to.equal(201);
    expect(request.headers['idempotency-key']).to.match(/^[a-f0-9-]{36}$/);
    expect(request.body).not.to.have.property('limit');
    expect(request.body).not.to.have.property('cursor');
    expect(Date.parse(request.body.asOf)).to.equal(Date.parse(c.asOf));
    const metadata = response!.body.data as AuditExportMetadata;
    expect(metadata.organizationId).to.equal(c.organizationId);
    cy.get(ready).should('have.attr', 'data-export-id', metadata.exportId);
    return cy.wrap(metadata, { log: false });
  });
}
function readDownload(
  c: Context,
  metadata: AuditExportMetadata,
  kind: 'csv' | 'metadata',
) {
  const fileName =
    kind === 'csv'
      ? metadata.fileName
      : metadata.fileName.replace(/\.csv$/, '.json');
  cy.readFile(`${Cypress.config('downloadsFolder')}/${fileName}`, null, {
    log: false,
    timeout: 15_000,
  }).should('exist');
  return cy.task<
    CsvDownload | { metadata: AuditExportMetadata; byteLength: number }
  >(
    'auditExport:readDownload',
    {
      organizationId: c.organizationId,
      exportId: metadata.exportId,
      fileName,
      kind,
    },
    { log: false },
  );
}
function downloadCsv(c: Context, metadata: AuditExportMetadata) {
  cy.get(csvButton).click();
  cy.contains(
    'CSV íntegro verificado y enviado al navegador para descarga.',
  ).should('be.visible');
  return readDownload(c, metadata, 'csv').then((result) => {
    const csv = result as CsvDownload;
    expect(csv.headerFields).to.deep.equal(headers);
    expect(csv.sha256).to.equal(metadata.sha256);
    expect(csv.byteLength).to.equal(metadata.byteLength);
    expect(csv.rowCount).to.equal(metadata.rowCount);
    expect(csv.rows.every((row) => row[6] === c.organizationId)).to.equal(true);
    return cy.wrap(csv, { log: false });
  });
}
function recordMeasurement(draft: Measurement) {
  return cy.task<{ samples: number; p95Ms: number; passed: boolean }>(
    'auditExport:performance',
    {
      organizationId: draft.organizationId,
      firstNavigationMs: draft.firstNavigationMs,
      firstNavigationValid: draft.firstNavigationValid,
      samples: draft.samples,
    },
    { log: false },
  );
}

describe('IMP-06.06 · Exportación privada de auditoría', () => {
  beforeEach(function () {
    const title = this.currentTest?.title ?? '';
    const profile = title.includes('EXPORT-02')
      ? 'hostile'
      : title.includes('EXPORT-03')
        ? 'rowOverflow'
        : title.includes('EXPORT-08')
          ? 'capacity'
          : 'functional';
    prepare(profile).as('exportContext');
  });
  afterEach(function () {
    releaseResponse?.();
    releaseResponse = undefined;
    const draft = measurement;
    measurement = null;
    if (draft && this.currentTest?.state === 'failed') {
      if (draft.startedAt !== null) {
        const durationMs = performance.now() - draft.startedAt;
        if (draft.index === 0) {
          draft.firstNavigationMs = durationMs;
          draft.firstNavigationValid = false;
        } else draft.samples.push({ durationMs, valid: false });
      }
      recordMeasurement(draft);
    }
  });

  it('IMP06-AUDIT-EXPORT-01 · Exportar desde una página posterior → CSV íntegro de todo el filtro y metadatos coherentes', () => {
    cy.get<Context>('@exportContext').then((c) => {
      visit(c);
      cy.get('[name="action"]').type('fixture.created');
      cy.get(generate).should('be.disabled');
      cy.get('[data-cy="audit-filters"]')
        .contains('button', 'Limpiar filtros')
        .click();
      cy.get(generate).should('be.enabled');
      cy.get('nav[aria-label="Páginas de auditoría"]')
        .contains('button', 'Siguiente página')
        .click();
      cy.get('[data-cy="audit-row"]').should('have.length', 5);
      startExport(c).then((metadata) => {
        expect(metadata.rowCount).to.equal(25);
        downloadCsv(c, metadata).then((csv) =>
          expect(new Set(csv.rows.map((row) => row[0])).size).to.equal(25),
        );
        cy.get(metaButton).click();
        cy.contains(
          'Metadatos verificados y enviados al navegador para descarga.',
        ).should('be.visible');
        readDownload(c, metadata, 'metadata').then((result) =>
          expect(
            (result as { metadata: AuditExportMetadata }).metadata,
          ).to.deep.equal(metadata),
        );
        cy.task<Facts>(
          'auditExport:facts',
          { organizationId: c.organizationId, exportId: metadata.exportId },
          { log: false },
        ).then((facts) => {
          expect(facts.generated).to.equal(1);
          expect(facts.downloaded).to.equal(1);
          expect(facts.exports).to.have.length(1);
          expect(facts.exports[0]!.storedBytes).to.equal(metadata.byteLength);
        });
      });
    });
  });

  it('IMP06-AUDIT-EXPORT-02 · Exportar texto hostil y una consulta vacía → formato seguro sin filas inventadas', () => {
    cy.get<Context>('@exportContext').then((c) => {
      visit(c);
      startExport(c).then((metadata) =>
        downloadCsv(c, metadata).then((csv) => {
          expect(csv.rowCount).to.equal(c.oracle.total);
          expect([...new Set(csv.rows.map((row) => row[3]))]).to.have.members([
            'texto: =1+1',
            'texto:  +SUM(A1:A2)',
            'texto: \\u0009@SUM(A1:A2)',
            'texto: -2+3',
            'texto: ＝1+1',
            'texto: \\u202e+1',
            'á, ñ, "texto"\r\nsegunda línea',
            'control\\u0001seguro',
          ]);
          expect(
            csv.rows.every((row) => !row.join('').includes('\u0001')),
          ).to.equal(true);
          expect(
            csv.rows.every(
              (row) => !row.join('').includes('audit-private-fixture-sentinel'),
            ),
          ).to.equal(true);
        }),
      );
      cy.get('[name="action"]').type('no.matches.audit.export');
      cy.get(generate).should('be.disabled');
      apply();
      cy.contains('No hay registros para estos filtros.').should('be.visible');
      startExport(c, 'emptyExport').then((metadata) => {
        expect(metadata.rowCount).to.equal(0);
        downloadCsv(c, metadata).then((csv) => {
          expect(csv.rows).to.have.length(0);
          expect(csv.headerFields).to.deep.equal(headers);
        });
      });
    });
  });

  it('IMP06-AUDIT-EXPORT-03 · Superar límites de filas o bytes → error recuperable sin archivo parcial', () => {
    function reject(c: Context) {
      const alias = `oversizedExport-${c.organizationId}`;
      visit(c);
      cy.intercept({
        method: 'POST',
        pathname: `/api/v1/organizations/${c.organizationId}/audit-exports`,
        times: 1,
      }).as(alias);
      cy.get(generate).click();
      cy.wait(`@${alias}`).then(({ request, response }) => {
        expect(new URL(request.url).pathname).to.equal(
          `/api/v1/organizations/${c.organizationId}/audit-exports`,
        );
        expect(response!.statusCode).to.equal(422);
        expect(response!.body.error.code).to.equal(
          'AUDIT_EXPORT_LIMIT_EXCEEDED',
        );
      });
      cy.contains('La consulta supera el límite de exportación.').should(
        'be.visible',
      );
      cy.get(ready).should('not.exist');
      cy.get(csvButton).should('not.exist');
      cy.get('[name="action"]').should('be.enabled');
      cy.task<Facts>(
        'auditExport:facts',
        { organizationId: c.organizationId },
        { log: false },
      ).then((facts) => {
        expect(facts.exports).to.have.length(1);
        expect(facts.failed).to.equal(1);
        expect(facts.exports[0]!.storedBytes).to.equal(0);
      });
    }
    cy.get<Context>('@exportContext').then((c) => {
      reject(c);
      cy.get('[name="actorId"]').type(c.filters.actorId);
      cy.get('[name="action"]').type(c.filters.action);
      cy.get('[name="entityType"]').type(c.filters.entityType);
      cy.get('[name="entityId"]').type(c.filters.entityId);
      apply();
      cy.get('[data-testid="audit-list-ready"]').should(
        'contain.text',
        `Registros encontrados: ${c.oracle.combinedTotal}.`,
      );
      startExport(c).then((metadata) =>
        expect(metadata.rowCount).to.equal(c.oracle.combinedTotal),
      );
    });
    prepare('byteOverflow').then(reject);
  });

  it('IMP06-AUDIT-EXPORT-04 · Perder la respuesta y recargar → recupera el mismo archivo con la misma clave', () => {
    cy.get<Context>('@exportContext').then((c) => {
      let lost = false;
      visit(c, (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !lost &&
              init?.method === 'POST' &&
              String(input).endsWith('/audit-exports') &&
              response.ok
            ) {
              lost = true;
              throw new TypeError('Explicit TEST lost POST response');
            }
            return response;
          });
      });
      cy.intercept({
        method: 'POST',
        pathname: `/api/v1/organizations/${c.organizationId}/audit-exports`,
      }).as('uncertainExport');
      cy.get(generate).click();
      cy.wait('@uncertainExport').then(({ request, response }) => {
        const key = request.headers['idempotency-key'];
        const originalMetadata = response!.body.data as AuditExportMetadata;
        cy.get('[data-cy="audit-export-recover"]').should('be.enabled');
        cy.get('[name="action"]').should('be.disabled');
        cy.reload();
        cy.get('[data-cy="audit-export-recover"]').should('be.enabled').click();
        cy.wait('@uncertainExport').then(
          ({ request: replay, response: replayed }) => {
            expect(replay.headers['idempotency-key']).to.equal(key);
            expect(replay.body).to.deep.equal(request.body);
            expect(replayed!.body.data).to.deep.equal(originalMetadata);
          },
        );
        cy.get(ready).should(
          'have.attr',
          'data-export-id',
          originalMetadata.exportId,
        );
        downloadCsv(c, originalMetadata);
        cy.task<Facts>(
          'auditExport:facts',
          { organizationId: c.organizationId },
          { log: false },
        ).then((facts) => {
          expect(facts.exports).to.have.length(1);
          expect(facts.generated).to.equal(1);
        });
      });
    });
  });

  it('IMP06-AUDIT-EXPORT-05 · Vencer un archivo o revocar acceso antes de descargar → no entrega el contenido', () => {
    cy.get<Context>('@exportContext').then((c) => {
      visit(c);
      startExport(c).then((metadata) => {
        cy.task(
          'auditExport:expire',
          { organizationId: c.organizationId, exportId: metadata.exportId },
          { log: false },
        );
        cy.get(csvButton).click();
        cy.contains('La exportación venció.').should('be.visible');
        cy.get(csvButton).should('be.disabled');
        cy.get(metaButton).should('be.disabled');
      });
      startExport(c, 'nextExport').then((metadata) => {
        cy.task(
          'auditExport:revoke',
          { organizationId: c.organizationId },
          { log: false },
        );
        cy.get(csvButton).click();
        cy.get('[role="alert"]').should('be.visible');
        cy.get('[data-cy="audit-export"]').should('not.exist');
        cy.task<Facts>(
          'auditExport:facts',
          { organizationId: c.organizationId, exportId: metadata.exportId },
          { log: false },
        ).then((facts) => expect(facts.downloaded).to.equal(0));
        cy.task(
          'auditExport:revoke',
          { organizationId: c.organizationId, restore: true },
          { log: false },
        );
      });
    });
  });

  it('IMP06-AUDIT-EXPORT-06 · Falla de servicio, pérdida de descarga y cierre de sesión → no crea archivos incompletos', () => {
    cy.get<Context>('@exportContext').then((c) => {
      let mode: 'lose' | 'pass' | 'hold' = 'lose';
      let blobs = 0;
      let aborted: AbortSignal | null | undefined;
      visit(c, (window) => {
        const original = window.fetch.bind(window);
        const createUrl = window.URL.createObjectURL.bind(window.URL);
        window.URL.createObjectURL = (blob) => {
          blobs++;
          return createUrl(blob);
        };
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              String(input).includes('/audit-exports/') &&
              String(input).endsWith('/content') &&
              response.ok
            ) {
              if (mode === 'lose') {
                mode = 'pass';
                throw new TypeError('Explicit TEST download response loss');
              }
              if (mode === 'hold') {
                aborted = init?.signal;
                return new Promise<Response>((resolve) => {
                  releaseResponse = () => resolve(response);
                });
              }
            }
            return response;
          });
      });
      startExport(c).then((metadata) => {
        cy.task('foundation:apiStop', null, { log: false });
        cy.get(csvButton).click();
        cy.get('[data-cy="audit-export"] [role="alert"]').should('be.visible');
        cy.then(() => expect(blobs).to.equal(0));
        cy.task('foundation:apiStart', null, { log: false });
        cy.get(csvButton).click();
        cy.contains('No se pudo completar la descarga.').should('be.visible');
        cy.then(() => expect(blobs).to.equal(0));
        downloadCsv(c, metadata);
        cy.then(() => {
          expect(blobs).to.equal(1);
          mode = 'hold';
        });
      });
      startExport(c, 'heldExport').then(() => {
        cy.get(csvButton).click();
        cy.wrap(null).should(() => expect(releaseResponse).to.be.a('function'));
        cy.contains('button', 'Cerrar sesión').click();
        cy.get('[data-cy="audit-export"]').should('not.exist');
        cy.then(() => {
          expect(aborted?.aborted).to.equal(true);
          releaseResponse!();
        });
        cy.then(() => expect(blobs).to.equal(1));
      });
    });
  });

  it('IMP06-AUDIT-EXPORT-07 · Generar y descargar con teclado → controles legibles en escritorio, tableta y móvil', () => {
    cy.get<Context>('@exportContext').then((c) => {
      for (const size of [
        { name: 'desktop', width: 1440, height: 900 },
        { name: 'tablet', width: 768, height: 1024 },
        { name: 'mobile', width: 390, height: 844 },
      ]) {
        const alias = `keyboardExport-${size.name}`;
        cy.viewport(size.width, size.height);
        visit(c);
        cy.intercept({
          method: 'POST',
          pathname: `/api/v1/organizations/${c.organizationId}/audit-exports`,
          times: 1,
        }).as(alias);
        cy.get(generate).focus();
        pressEnterInChrome();
        cy.wait(`@${alias}`).then(({ response }) => {
          expect(response!.statusCode).to.equal(201);
          const metadata = response!.body.data as AuditExportMetadata;
          expect(metadata.organizationId).to.equal(c.organizationId);
          cy.get(ready).should(
            'have.attr',
            'data-export-id',
            metadata.exportId,
          );
          cy.get('[data-cy="audit-export"]').scrollIntoView();
          cy.document().should((document) =>
            expect(document.documentElement.scrollWidth).to.be.at.most(
              document.documentElement.clientWidth + 1,
            ),
          );
          cy.screenshot(`imp06-audit-export-${size.name}`, {
            capture: 'viewport',
            overwrite: true,
          });
          cy.get(csvButton).focus();
          pressEnterInChrome();
          cy.contains(
            'CSV íntegro verificado y enviado al navegador para descarga.',
          ).should('be.visible');
          readDownload(c, metadata, 'csv');
          pressKeyInChrome('Tab');
          cy.get(metaButton).should('be.focused');
          pressEnterInChrome();
          cy.contains(
            'Metadatos verificados y enviados al navegador para descarga.',
          ).should('be.visible');
          readDownload(c, metadata, 'metadata');
        });
      }
    });
  });

  it('IMP06-AUDIT-EXPORT-08 · Exportar 10000 eventos aislados → primera navegación separada y 50 descargas completas bajo p95 de 3 s', () => {
    cy.get<Context>('@exportContext').then((c) => {
      expect(c.oracle.total).to.equal(10000);
      expect(c.oracle.foreignTotal).to.equal(1000);
      const draft: Measurement = {
        organizationId: c.organizationId,
        firstNavigationMs: null,
        firstNavigationValid: false,
        samples: [],
        startedAt: null,
        index: 0,
      };
      cy.then(() => {
        measurement = draft;
      });
      for (let index = 0; index <= 50; index++) {
        cy.then(() => {
          draft.startedAt = performance.now();
          draft.index = index;
        });
        visit(c);
        startExport(c, `measuredExport${index}`).then((metadata) => {
          expect(metadata.rowCount).to.equal(10000);
          cy.get(csvButton).click();
          cy.contains(
            'CSV íntegro verificado y enviado al navegador para descarga.',
          ).should('be.visible');
          cy.then(() => {
            const durationMs = performance.now() - draft.startedAt!;
            draft.startedAt = null;
            if (index === 0) {
              draft.firstNavigationMs = durationMs;
              draft.firstNavigationValid = true;
            } else draft.samples.push({ durationMs, valid: true });
          });
          // Validate the persisted browser artifact independently after the UI clock stops.
          readDownload(c, metadata, 'csv');
        });
      }
      cy.then(() => recordMeasurement(draft)).then((result) => {
        expect(result.samples).to.equal(50);
        expect(result.p95Ms).to.be.lessThan(3000);
        expect(result.passed).to.equal(true);
        measurement = null;
      });
    });
  });
});
